// Spec: cypress/e2e/specs/pim-employee-management-2026-10-21.feature
// Covers: view/edit employee, @boundary, @error, @security scenarios not in orangehrm-pim.cy.js
// Generated by: /tw-e2e-spec-to-test
import PIMPage from '../support/pages/PIMPage';
import NavigationComponent from '../support/pages/NavigationComponent';

describe('PIM Employee Management — Extended Coverage', () => {

  describe('@boundary — Search Edge Cases', () => {
    beforeEach(() => {
      cy.loginWithEnvCredentials();
      NavigationComponent.navigateToPIM();
    });

    // Feature: Search with no criteria returns all employees
    it('@boundary — Clicking Search without criteria returns the full employee list', () => {
      PIMPage.clickSearch();

      cy.get('.oxd-table-body').should('be.visible');
      // Should show multiple rows — not zero
      cy.get('.oxd-table-body .oxd-table-row').should('have.length.gte', 1);
    });

    // Feature: Searching for non-existent employee ID returns empty table
    it('@boundary — Search for non-existent Employee ID shows empty state without error', () => {
      PIMPage
        .searchForEmployee('ZZZZ9999')
        .clickSearch();

      cy.get('.oxd-table-body').should('be.visible');
      cy.contains('No Records Found').should('be.visible');
    });
  });

  describe('@happy — View and Edit Employee', () => {
    beforeEach(() => {
      cy.loginWithEnvCredentials();
      NavigationComponent.navigateToPIM();
    });

    // Feature: Admin views an existing employee's personal details page
    it('@happy — Clicking an employee record opens their Personal Details page', () => {
      // Search first, then click the first result's edit/view link
      PIMPage.clickSearch();

      cy.get('.oxd-table-body .oxd-table-row').first().within(() => {
        cy.get('button').first().click(); // Edit button (pencil icon)
      });

      // Verify personal details page loads
      cy.url().should('include', '/viewPersonalDetails/empNumber');
      cy.contains('h6', 'Personal Details').should('be.visible');
    });

    // Feature: Admin updates employee details
    it('@happy — Editing employee middle name saves successfully', () => {
      PIMPage.clickSearch();

      cy.get('.oxd-table-body .oxd-table-row').first().within(() => {
        cy.get('button').first().click();
      });

      cy.url().should('include', '/viewPersonalDetails/empNumber');

      // Update middle name
      cy.get(PIMPage.middleNameInput).clear().type('UpdatedMiddle');

      cy.contains('button', 'Save').first().click();

      // Verify success toast or URL stays on same page with no error
      cy.get('[class*="toast--success"], .oxd-toast--success').should('be.visible');
    });
  });

  describe('@error — Add Employee Form Validation', () => {
    beforeEach(() => {
      cy.loginWithEnvCredentials();
      NavigationComponent.navigateToPIM();
    });

    // Feature: Save without First Name and Last Name shows required errors
    it('@error — Add Employee form without First Name shows required field error', () => {
      PIMPage.clickAdd();
      PIMPage.verifyAddEmployeePage();

      // Clear auto-populated fields and submit
      cy.get(PIMPage.firstNameInput).clear();
      cy.get(PIMPage.lastNameInput).clear();

      cy.contains('button', 'Save').click();

      cy.get('.oxd-input-field-error-message').should('have.length.gte', 1);
      cy.get('.oxd-input-field-error-message').first().should('contain', 'Required');
    });

    // Feature: Mismatched passwords on Add Employee login details
    it('@error — Mismatched Create Login Details passwords shows validation error', () => {
      PIMPage.clickAdd();
      PIMPage.verifyAddEmployeePage();

      cy.fixture('orangehrm').then((data) => {
        PIMPage.fillEmployeeDetails(
          data.employeeData.firstName,
          data.employeeData.middleName,
          data.employeeData.lastName
        );

        PIMPage.toggleCreateLoginDetails();

        // Intentionally mismatched passwords
        PIMPage.fillLoginDetails('e2e_user_mismatch', 'Pass123!', 'Different456!');

        cy.contains('button', 'Save').click();

        cy.get('.oxd-input-field-error-message')
          .should('contain.text', 'Passwords do not match');
      });
    });
  });

  describe('@security — Authorization', () => {
    // Feature: Unauthenticated user cannot access PIM
    it('@security — Unauthenticated user accessing PIM is redirected to login', () => {
      cy.visit('/pim/viewEmployeeList', { failOnStatusCode: false });
      cy.url().should('include', '/auth/login');
      cy.get('input[name="username"]').should('be.visible');
    });

    // Feature: XSS payload in employee name search field
    it('@security — XSS payload in Employee Name search field is not executed', () => {
      cy.loginWithEnvCredentials();
      NavigationComponent.navigateToPIM();

      cy.on('window:alert', () => {
        throw new Error('XSS payload was executed — alert dialog appeared');
      });

      // Employee Name is an autocomplete — type payload into it
      cy.contains('.oxd-label', 'Employee Name')
        .closest('.oxd-input-group')
        .find('input')
        .type("<script>alert('xss')</script>");

      PIMPage.clickSearch();
      cy.get('.oxd-table').should('be.visible');
    });
  });

  describe('@contract — API Behavior', () => {
    beforeEach(() => {
      cy.loginWithEnvCredentials();
      NavigationComponent.navigateToPIM();
    });

    // Feature: Employee list API does not return 5xx
    it('@contract — Employee List API returns valid response without server error', () => {
      // Intercept before the action that triggers the request
      cy.intercept('GET', /viewEmployeeList|\/api\/v2\/pim\/employees/).as('employeeList');

      NavigationComponent.navigateToPIM();

      cy.wait('@employeeList', { timeout: 15000 }).then((interception) => {
        expect(interception.response.statusCode).to.be.lessThan(500);
      });

      PIMPage.verifyTableVisible();
    });

    // Feature: Employee search API returns filtered results
    it('@contract — Employee search API responds without 5xx error', () => {
      // Intercept must be registered before the search action fires the request
      cy.intercept('GET', /viewEmployeeList|\/api\/v2\/pim\/employees/).as('searchEmployees');

      PIMPage.searchForEmployee('0001').clickSearch();

      cy.wait('@searchEmployees', { timeout: 15000 }).then((interception) => {
        expect(interception.response.statusCode).to.be.lessThan(500);
      });
    });
  });
});
